import React, { createContext, useState, useEffect, useContext, useRef } from 'react';
import api from '../services/api';
import { useNotification } from './NotificationContext'; // Подключаем контекст колокольчика/уведомлений

const AuthContext = createContext(null);

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth должен использоваться внутри AuthProvider');
  }
  return context;
};

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [theme, setTheme] = useState(localStorage.getItem('theme') || 'light');

  // Извлекаем единый метод для добавления уведомлений в колокольчик
  const { addNotification } = useNotification();

  // Рефы для контроля состояний и предотвращения дубликатов при маунте
  const isFirstAdminFetch = useRef(true);
  const isFirstClientFetch = useRef(true);
  const seenAppsRef = useRef(new Set());
  const prevLoansRef = useRef({});

  // Проверка сессии при загрузке приложения
  useEffect(() => {
    api.get('/auth/me')
      .then(res => setUser(res.data))
      .catch(() => setUser(null))
      .finally(() => setLoading(false));
  }, []);

  // Управление темой оформления
  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
    localStorage.setItem('theme', theme);
  }, [theme]);

  const toggleTheme = () => {
    setTheme(prev => prev === 'light' ? 'dark' : 'light');
  };

  // Авторизация
  const login = async (email, password) => {
    const res = await api.post('/auth/login', { email, password });
    localStorage.setItem('token', res.data.access_token);
    const userRes = await api.get('/auth/me');
    setUser(userRes.data);
    
    // Сбрасываем кэш рефов для нового вошедшего пользователя
    isFirstAdminFetch.current = true;
    isFirstClientFetch.current = true;
    seenAppsRef.current = new Set();
    prevLoansRef.current = {};
    
    return res.data;
  };

  // Выход из системы
  const logout = async () => {
    try {
      await api.post('/auth/logout');
    } catch (err) {
      console.error('Ошибка при выходе:', err);
    }
    localStorage.removeItem('token');
    setUser(null);
  };

  // Периодический поллинг (резервный механизм параллельно с WebSocket)
  useEffect(() => {
    if (!user) return;

    // 1. Для Администраторов и Менеджеров — отслеживание новых заявок
    const fetchNewApplications = async () => {
      if (user.role !== 'admin' && user.role !== 'manager') return;
      try {
        // Запрос к панели админа (подстраивается под структуру вашего эндпоинта)
        const res = await api.get('/admin/stats');
        // Здесь при необходимости можно обрабатывать новые входящие ID
      } catch (err) {
        console.error('Ошибка получения заявок админом:', err);
      }
    };

    // 2. Для Клиентов — отслеживание изменения вердиктов по ИХ кредитам
    const checkClientLoanStatuses = async () => {
      // Администраторам и менеджерам не нужно слушать изменение статусов личных кредитов
      if (user.role === 'admin' || user.role === 'manager') return;
      
      try {
        const res = await api.get('/loans/my');
        const currentLoans = res.data || [];

        currentLoans.forEach(loan => {
          const prevLoan = prevLoansRef.current[loan.id];

          if (isFirstClientFetch.current) {
            // Первым проходом просто сохраняем текущую базу, чтобы не спамить старыми уведомлениями
            prevLoansRef.current[loan.id] = loan;
            return;
          }

          // ИСПРАВЛЕНО: Уведомляем только если заявка Раньше Была в системе И её статус изменился
          if (prevLoan && prevLoan.status !== loan.status) {
            // Реагируем только на финальные решения: одобрено (approved) или отклонено (rejected)
            if (loan.status === 'approved' || loan.status === 'rejected') {
              const statusRu = loan.status === 'approved' ? 'одобрена' : 'отклонена';
              const notifType = loan.status === 'approved' ? 'success' : 'error';
              
              addNotification(`Ваша заявка на кредит №${loan.id} была ${statusRu}!`, notifType);
            }
          }

          // Запоминаем текущий статус для следующей проверки через 5 секунд
          prevLoansRef.current[loan.id] = loan;
        });

        isFirstClientFetch.current = false;
      } catch (err) {
        console.error('Ошибка проверки статуса кредитов:', err);
      }
    };

    // Синхронизация уведомлений между открытыми вкладками браузера через localStorage
    const handleStorageNotification = (e) => {
      if (e.key === 'luxury_dealer_new_app' && (user.role === 'admin' || user.role === 'manager')) {
        try {
          const appData = JSON.parse(e.newValue);
          if (appData) {
            const appName = String(appData.type).toLowerCase() === 'loan' ? 'кредит' : 'тест-драйв';
            const msg = `🔥 Мгновенно: Получена заявка на ${appName}!`;
            addNotification(msg, 'warning');
          }
        } catch (err) {
          console.error(err);
        }
      }
    };

    // Настройка интервала поллинга (каждые 5 секунд)
    const interval = setInterval(() => {
      fetchNewApplications();
      checkClientLoanStatuses();
    }, 5000);

    // Вызываем сразу при маунте, чтобы не ждать первые 5 секунд
    fetchNewApplications();
    checkClientLoanStatuses();

    window.addEventListener('storage', handleStorageNotification);

    return () => {
      clearInterval(interval);
      window.removeEventListener('storage', handleStorageNotification);
    };
  }, [user, addNotification]);

  return (
    <AuthContext.Provider value={{ user, loading, login, logout, theme, toggleTheme }}>
      {children}
    </AuthContext.Provider>
  );
};
